insert into public.puzzles (id, owner_id, size, setup, answers, title, prompt, explanation, difficulty) values
 ('a01', null, 9, '{"rows":[".........",".........",".........","....X....","...XTX...",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas encore. La pierre blanche a toujours un point vide à côté d''elle, en E4. Tant que ce point est libre, elle reste sur le plateau."}', array['E4'], 'Première capture', 'Capture tout de suite la pierre blanche marquée.', 'Bravo ! Les points vides juste à côté d''une pierre sont ses libertés. La pierre blanche n''en avait plus qu''une, E4 : elle était en atari. En occupant E4, tu lui retires sa dernière liberté et tu la captures.', 300),
 ('a02', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".........",".........","...XTX..."],"toPlay":"B","refutation":"Pas encore. Sur le bord, une pierre a moins de libertés. Celle-ci n''en a plus qu''une : cherche le point vide juste au-dessus d''elle."}', array['E2'], 'Capture au bord', 'Capture tout de suite la pierre blanche marquée, sur le bord.', 'Exact ! Les libertés d''une pierre sont les points vides juste à côté d''elle. Au bord, il n''y en a que trois au départ. Ici, il n''en restait qu''une, E2 : la pierre était en atari, et E2 la capture.', 320),
 ('a03', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".........",".........","TX......."],"toPlay":"B","refutation":"Pas encore. Dans le coin, une pierre n''a que deux libertés au départ. Ta pierre B1 en occupe déjà une : il reste l''autre."}', array['A2'], 'Capture dans le coin', 'Capture tout de suite la pierre blanche marquée, dans le coin.', 'Bien joué ! Les libertés d''une pierre sont les points vides juste à côté d''elle. Dans le coin, il n''y en a que deux. Ta pierre B1 en prenait une ; la pierre blanche était donc en atari (une seule liberté), et A2 la capture.', 340),
 ('a04', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".........","...X.....","..XTOX..."],"toPlay":"B","refutation":"Pas encore. Les deux pierres blanches se touchent : elles forment un seul groupe et partagent leurs libertés. Il ne leur en reste qu''une."}', array['E2'], 'Deux pierres au bord', 'Capture tout de suite les deux pierres blanches, sur le bord.', 'Parfait ! Deux pierres qui se touchent par un côté forment un groupe : elles vivent et meurent ensemble. Ce groupe n''avait plus qu''une liberté (un point vide à côté de lui), E2. Il était en atari : E2 prend les deux pierres d''un coup.', 380),
 ('a05', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".........","TX.......","OX......."],"toPlay":"B","refutation":"Pas encore. Les deux pierres blanches du coin forment un seul groupe. Compte ses libertés : il ne lui reste qu''un point vide, au-dessus."}', array['A3'], 'Deux pierres dans le coin', 'Capture tout de suite les deux pierres blanches du coin.', 'Très bien ! Les pierres A1 et A2 se touchent : c''est un groupe. Ses libertés, les points vides à côté de lui, se réduisaient à A3. Il était en atari ; A3 capture les deux pierres.', 400),
 ('a06', null, 9, '{"rows":[".........",".........",".........","...XXX...","..XOTOX..","...X.X...",".........",".........","........."],"toPlay":"B","refutation":"Pas encore. Les trois pierres blanches forment un seul groupe. Regarde tout autour : un seul point vide le touche encore."}', array['E4'], 'Un groupe de trois', 'Capture tout de suite le groupe de trois pierres blanches.', 'Bravo ! Un groupe se capture comme une pierre seule : on occupe toutes ses libertés, les points vides qui le touchent. Il ne lui restait que E4 : il était en atari. Tu prends trois pierres d''un coup.', 420),
 ('a07', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........",".O.......",".SO......","TX.O....."],"toPlay":"B","refutation":"Pas tout à fait. Tes deux pierres n''ont que deux libertés. Si tu t''allonges en C1, elles n''en ont plus qu''une et Blanc les capture en A2. Regarde plutôt la pierre blanche du coin : elle est en atari."}', array['A2'], 'Capture pour te sauver', 'Tes pierres sont menacées. Capture tout de suite la pierre blanche marquée pour les sauver.', 'Exact ! La pierre A1 n''avait qu''une liberté (un point vide à côté d''elle), A2 : elle était en atari. En la capturant, tes pierres gagnent de l''air : elles ont maintenant trois libertés, A1, A3 et C1. Capturer une pierre qui te serre, c''est souvent la meilleure défense.', 450),
 ('a08', null, 9, '{"rows":["..XTS.O..","....OO...",".........",".........",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Ta pierre marquée n''a qu''une liberté, F9, et s''y allonger serait un suicide : ta pierre n''aurait plus aucun point vide. La pierre blanche D9, elle, est en atari."}', array['D8'], 'Sors de la boîte', 'Ta pierre marquée ne peut pas s''allonger. Capture tout de suite la pierre blanche marquée pour la sauver.', 'Bravo ! Les libertés sont les points vides à côté d''une pierre. La pierre blanche D9 n''en avait qu''une, D8 : elle était en atari, et tu la captures. Ta pierre E9 gagne une liberté en D9 et garde F9. En F9, elle n''en aurait eu aucune : un coup interdit, le suicide.', 460),
 ('a09', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........","....X....","...XT....","........."],"toPlay":"B","refutation":"Pas celle-là. Après E1, Blanc s''allonge en F2, vers le centre : il a trois libertés et s''échappe. Mets-le en atari de l''autre côté, pour le pousser vers le bord."}', array['F2'], 'Pousse vers le bord', 'Mets la pierre marquée en atari du bon côté, puis capture-la.', 'Bien vu ! Mettre en atari, c''est laisser une seule liberté (un point vide à côté) à une pierre. Après F2, Blanc s''allonge en E1, mais sur le bord il n''a que deux libertés, D1 et F1. Tu joues D1 : atari. Il s''allonge en F1, et tu le captures en G1. Le bord est un mur : pousse l''adversaire contre lui.', 480),
 ('a10', null, 9, '{"rows":[".........",".........",".........","....XX...","...XT.X..",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas celle-là. Après F5, Blanc s''allonge en E4, vers le bas : il a trois libertés et s''échappe. Pousse-le plutôt vers tes pierres F6 et G5."}', array['E4'], 'Vers tes pierres', 'Mets la pierre marquée en atari en la poussant vers tes pierres, et capture-la.', 'Excellent ! La pierre avait deux libertés (points vides à côté d''elle), E4 et F5. Après E4, elle est en atari : il ne lui reste que F5. Si Blanc s''allonge en F5, tes pierres F6 et G5 l''attendent : il n''a toujours qu''une liberté, F4, et tu le captures.', 520),
 ('a11', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........","..X.X....",".XT.TX...","........."],"toPlay":"B","refutation":"Pas tout à fait. Si tu mets une seule pierre en atari, Blanc joue D2 : il relie ses deux pierres et s''échappe. Cherche le point qui touche les deux."}', array['D2'], 'Double atari au bord', 'Un seul coup menace les deux pierres marquées. Trouve-le, puis capture.', 'Bravo ! En D2, tu mets les deux pierres en atari à la fois : il ne reste à chacune qu''une liberté (un point vide à côté d''elle), C1 pour l''une, E1 pour l''autre. C''est un double atari. Blanc ne peut en sauver qu''une ; tu captures l''autre au coup suivant.', 540),
 ('a12', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........","..X......","..TX.....","........."],"toPlay":"B","refutation":"Pas celle-là. Après C1, Blanc s''allonge en B2, vers l''extérieur : il a trois libertés et s''échappe. Pousse-le vers le coin."}', array['B2'], 'Pousse vers le coin', 'Mets la pierre marquée en atari du bon côté, puis capture-la.', 'Exact ! Après B2, la pierre est en atari : une seule liberté (point vide à côté), C1. Si Blanc s''allonge en C1, il n''a que deux libertés, B1 et D1. Tu joues D1, il s''allonge en B1, et tu le captures en A1. Le coin est l''endroit où l''on a le moins de libertés.', 560),
 ('a13', null, 9, '{"rows":[".........",".........",".........",".........",".........",".X.X.....","XT.TX....",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Si tu ne menaces qu''une pierre, Blanc joue C3 : il relie ses deux pierres et leur donne assez de libertés. Cherche le point commun."}', array['C3'], 'Le point commun', 'Les deux pierres marquées ont un point vide en commun. Joue le double atari, puis capture.', 'Bien joué ! Chaque pierre avait deux libertés (points vides à côté d''elle), dont C3 en commun. En C3, tu mets les deux en atari à la fois : c''est un double atari. Blanc en sauve une, tu prends l''autre.', 600),
 ('a14', null, 9, '{"rows":["XOOXX....","SXTOX....","....X....",".........",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas le plus rapide. Compte les libertés : ton groupe marqué en a deux, A7 et B7, et le groupe blanc aussi, C7 et D7. Celui qui joue le premier gagne : retire une liberté au groupe blanc tout de suite."}', array['C7'], 'Qui a le plus de libertés ?', 'Ton groupe marqué et le groupe blanc marqué se serrent. Capture le groupe blanc en deux coups.', 'Bravo ! Les libertés sont les points vides à côté d''un groupe. Ton groupe en avait deux, le groupe blanc aussi : le premier qui joue gagne. Après C7, le groupe blanc est en atari (une seule liberté, D7). S''il s''allonge en D7, il reste en atari ; s''il attaque ton groupe, tu le captures en D7 avant.', 650),
 ('a15', null, 9, '{"rows":[".........",".........",".........","X........","TX.......",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas encore. Sur le bord, la pierre blanche n''a que trois points vides autour d''elle au départ. Tes pierres en occupent deux : il reste le dernier, juste en dessous."}', array['A4'], 'Capture sur le côté', 'Capture tout de suite la pierre blanche marquée, sur le bord gauche.', 'Exact ! Les libertés d''une pierre sont les points vides juste à côté d''elle. Sur le bord, elle n''en a que trois. Tes pierres A6 et B5 en prenaient deux : la pierre était en atari (une seule liberté), et A4 la capture.', 360),
 ('a16', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........","XX.......","OOX......","TO......."],"toPlay":"B","refutation":"Pas encore. Les quatre pierres blanches du coin se touchent : c''est un seul groupe. Fais le tour : un seul point vide le touche encore."}', array['C1'], 'Quatre pierres dans le coin', 'Capture tout de suite le groupe blanc du coin.', 'Bravo ! Les pierres qui se touchent forment un groupe, et il partage ses libertés, les points vides à côté de lui. Celui-ci n''en avait plus qu''une, C1 : il était en atari. Tu captures quatre pierres d''un coup.', 440),
 ('a17', null, 9, '{"rows":[".........",".........","X........","T........","S.O......","O........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Ta pierre marquée n''a qu''une liberté, B5. La pierre blanche A6, juste au-dessus, n''en a qu''une aussi : prends-la avant que Blanc ne prenne la tienne."}', array['B6'], 'Sauve-toi sur le bord', 'Ta pierre marquée est en atari. Capture tout de suite la pierre blanche marquée pour la sauver.', 'Bien joué ! Les libertés sont les points vides à côté d''une pierre. La pierre blanche A6 n''en avait qu''une, B6 : elle était en atari, et tu la captures. Ta pierre A5 respire : elle a maintenant deux libertés, A6 et B5.', 470),
 ('a18', null, 9, '{"rows":[".........",".........","....X....","...XTX...","...X.X...","...XOX...","....X....",".........","........."],"toPlay":"B","refutation":"Pas encore. Regarde le point vide au milieu : les deux pierres blanches n''ont plus que lui comme liberté, et tes pierres D5 et F5 s''y relient."}', array['E5'], 'Relie et capture', 'Un seul coup relie tes pierres et capture tout de suite.', 'Superbe ! Les libertés sont les points vides à côté d''une pierre. Les pierres blanches E6 et E4 n''en avaient qu''une chacune, la même : E5. Elles étaient en atari. En E5, tu les captures toutes les deux et tu relies tes pierres D5 et F5.', 500),
 ('a19', null, 9, '{"rows":[".....XTSX",".......O.",".........",".........",".........",".........",".........",".........","........."],"toPlay":"B","refutation":"Pas tout à fait. Tes deux pierres du coin n''ont qu''une liberté, J8. Si tu t''y allonges, elles n''en ont toujours qu''une, J7, et Blanc les capture. La pierre blanche G9, elle, est en atari."}', array['G8'], 'Sors du coin', 'Tes pierres du coin sont en atari. Capture tout de suite la pierre blanche marquée pour les sauver.', 'Bravo ! Les libertés sont les points vides à côté d''un groupe. La pierre blanche G9 n''en avait qu''une, G8 : elle était en atari, et tu la captures. Tes pierres du coin gagnent une liberté en G9 et gardent J8 : elles en ont deux. En J8, elles seraient restées en atari.', 530),
 ('a20', null, 9, '{"rows":[".........",".........",".........",".........",".........",".........","..X.X....","..XOX....","..XTX...."],"toPlay":"B","refutation":"Pas encore. Les deux pierres blanches coupent tes pierres en deux. Elles forment un seul groupe, et il ne lui reste qu''un point vide, au-dessus."}', array['D3'], 'Enlève la coupe', 'Les pierres blanches coupent tes pierres. Capture-les tout de suite.', 'Exact ! Les deux pierres blanches se touchent : c''est un groupe, avec une seule liberté (point vide à côté de lui), D3. Il était en atari. En D3, tu le captures, et tes pierres de gauche et de droite ne sont plus coupées.', 490)
